import asyncio
from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
from httpx import Response

app = FastAPI()

@app.post("/upload_1")
async def upload_1(form_data: str = Form(...), file_data: bytes = File(...)):
    return {"form_data": form_data, "file_data": file_data}

@app.post("/upload_2")
async def upload_2(file_data: bytes = File(...), form_data: str = Form(...)):
    return {"form_data": form_data, "file_data": file_data}

client = TestClient(app)

def test_upload_1():
    print("Testing /upload_1 (Form then File)...")
    response = client.post(
        "/upload_1",
        data={"form_data": "hello"},
        files={"file_data": b"world"}
    )
    print(f"Status: {response.status_code}")
    print(f"Body: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "file_data": b"world"}

def test_upload_2():
    print("Testing /upload_2 (File then Form)...")
    response = client.post(
        "/upload_2",
        data={"form_data": "hello"},
        files={"file_data": b"world"}
    )
    print(f"Status: {response.status_code}")
    print(f"Body: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "file_data": b"world"}

if __name__ == "__main__":
    try:
        test_upload_1()
        print("test_upload_1 passed!")
        test_upload_2()
        print("test_upload_2 passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

